window.RP_SESSION={"id":"S-ff9a42536407","messages":[{"id":"RP-III-0056741","time":"2026-03-28T12:23:00+09:00","room":"RP III","name":"토르번 팔켄하인 / 대장장이·도란","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"...","characters":["P-7ba611cf90be"]},{"id":"RP-III-0056742","time":"2026-03-28T12:23:00+09:00","room":"RP III","name":"토르번 팔켄하인 / 대장장이·도란","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"...","characters":["P-7ba611cf90be"]},{"id":"RP-III-0056743","time":"2026-03-28T12:23:00+09:00","room":"RP III","name":"토르번 팔켄하인 / 대장장이·도란","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"...","characters":["P-7ba611cf90be"]},{"id":"RP-III-0056744","time":"2026-03-28T12:24:00+09:00","room":"RP III","name":"토르번 팔켄하인 / 대장장이·도란","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"주말에 북적북적한 시장.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0056745","time":"2026-03-28T12:25:00+09:00","room":"RP III","name":"토르번 팔켄하인 / 대장장이·도란","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"션 형씨한테 검도 하나 사주고, 술도 한잔 나눠 먹으려 했는데 영 시간이 맞질 않는다.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0056746","time":"2026-03-28T12:25:00+09:00","room":"RP III","name":"토르번 팔켄하인 / 대장장이·도란","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"검이라도 사서 줄 생각으로 혼자서라도 마을 대장간을 찾는다.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0056747","time":"2026-03-28T12:26:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"그 시각 션은…… 재단사 가게에 있는 중이었다.","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056748","time":"2026-03-28T12:28:00+09:00","room":"RP III","name":"토르번 팔켄하인 / 대장장이·도란","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"시장의 인파를 지나던 중, 가게 안에서 익숙한 덩치가 눈에 띄었다.\n\n\"션 형씨?\"\n\n저걸 못 알아볼 순 없지.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0056749","time":"2026-03-28T12:37:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"돌아본 션은 어쩐 일인지 망토도 없고 서코트도 없었다. 가죽 조끼만 입은 그 어느 때보다 가벼운 차림새.\n\n\"오, 토르번 군.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056750","time":"2026-03-28T12:38:00+09:00","room":"RP III","name":"토르번 팔켄하인 / 대장장이·도란","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"여긴 어쩐 일인가. 옷 만들려고?\"\n\n멈춰서서는 그를 바라보다 가게 안으로 들어온다.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0056751","time":"2026-03-28T12:44:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"걸터앉아있어도 남들과 머리 위치가 엇비슷했다.\n\n\"맞네. 망토와 몇가지 옷감을 고쳐서 코트를 만들어달라고 했지.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056752","time":"2026-03-28T12:44:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"\"살다보니 망토는 너무 실용성이 부족해서 말이야.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056753","time":"2026-03-28T12:46:00+09:00","room":"RP III","name":"토르번 팔켄하인 / 대장장이·도란","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"아무래도 확실히.\"\n\n그는 대충 작은 나무를 곁으로 끌고와 재단사가 열일하는 풍경을 구경하며 책상에 기대앉았다.\n\n\"마침 잘됐군.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0056754","time":"2026-03-28T12:47:00+09:00","room":"RP III","name":"토르번 팔켄하인 / 대장장이·도란","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"안 그래도 형씨한테 줄 검을 사러가던 길이었는데, 기다릴테니 같이 가지.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0056755","time":"2026-03-28T12:56:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"\"참 신기하지 않나? 길드원이 50명이 넘는데 옷 만들 줄 아는 재봉사가 한 명도 없어.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056756","time":"2026-03-28T12:56:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"\"잡기술 배울 시간에 그런 거나 좀 배우지….\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056757","time":"2026-03-28T12:57:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"션이 고개를 털레털레 내저으며 담배를 입에 물었다. 키가 작고 깡마른 체형의 데미간 재단사는 오거라도 되는 것처럼 팔을 열심히 움직였다.","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056758","time":"2026-03-28T13:00:00+09:00","room":"RP III","name":"토르번 팔켄하인 / 대장장이·도란","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"전문가는 아니더라도 취미 정도 쯤은 몇 명 있을 법도 한데.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0056759","time":"2026-03-28T13:00:00+09:00","room":"RP III","name":"토르번 팔켄하인 / 대장장이·도란","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"길드에 별종들도 많은데 재봉사 한멍 있으면 편하기는 하겠군.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0056760","time":"2026-03-28T13:01:00+09:00","room":"RP III","name":"토르번 팔켄하인 / 대장장이·도란","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"옆에 걸려있는 원단을 손끝으로 만지작. 딴청을 피우며 그를 기다린다.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0056761","time":"2026-03-28T13:07:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"재단사 데미간이 두 손을 맞잡고 다가와 이틀을 달라고 했다.","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056762","time":"2026-03-28T13:08:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"\"흠, 워낙 커서 그런가.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056763","time":"2026-03-28T13:08:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"\"토르번 군, 가도록 하지.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056764","time":"2026-03-28T13:09:00+09:00","room":"RP III","name":"토르번 팔켄하인 / 대장장이·도란","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"하아암. 어젯밤 제대로 못 잤는지 하품을 하던 와중. 끝났다는 희소식에 냉큼 일어났다.\n\n\"좋아. 감세.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0056765","time":"2026-03-28T13:13:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"\"근데 아는 대장간이라도 있나?\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056766","time":"2026-03-28T13:14:00+09:00","room":"RP III","name":"토르번 팔켄하인 / 대장장이·도란","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"그대로 가게를 나가려다가 방향을 잃고 우뚝 멈춰선다.\n\n\"아니. 그냥 여기저기 둘러볼 생각이었네만.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0056767","time":"2026-03-28T13:15:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"\"남자랑 데이트 하기는 싫은데….\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056768","time":"2026-03-28T13:15:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"가면 밖으로도 다 들리도록 크게 한숨을 내쉬었다.","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056769","time":"2026-03-28T13:16:00+09:00","room":"RP III","name":"토르번 팔켄하인 / 대장장이·도란","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"키득키득. 장난스레 입꼬리만 웃고는\n\n\"자네도 아는 곳 없나? 그럼 어쩔 수 없지. 가끔은 남정네랑도 놀자고.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0056770","time":"2026-03-28T13:20:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"\"아이고, 신이시여. 길드원들이 무능하니 내가 거시기 달린 놈과 길을 걷는구나.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056771","time":"2026-03-28T13:23:00+09:00","room":"RP III","name":"토르번 팔켄하인 / 대장장이·도란","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"그 뭐야. 원래 믿을만한 동성 친구랑 노는 모습을 자주 보여줘야 외박 허가받기가 쉬운 법일세.\"\n\n거리를 둘러보며 길을 나섭니다.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0056772","time":"2026-03-28T13:28:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"\"난 허가 같은 거 안 받는다네.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056773","time":"2026-03-28T13:28:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"쇠냄새가 나는 길에 접해서 주변을 둘러보았다. 이 곳만이 열기가 유독 심하다.","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056774","time":"2026-03-28T13:31:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"어린 도제들이 길 쪽으로 나와서 흥정을 하거나 물건을 지나가는 이들에게 들이댄다.","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056775","time":"2026-03-28T13:35:00+09:00","room":"RP III","name":"토르번 팔켄하인 / 대장장이·도란","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"아주 상남자 납시셨어.\"\n\n거리 안쪽에서는 가마의 열을 올리는 후끈한 공기와 쇠 두들기는 소리, 땀내나는 험악한 장인들의 매서운 눈길 등으로 가득했다. 흥정을 하는 꼬맹이들을 무시하고 지나며 대장간 안쪽을 유심히 보며 다닌다.\n\n\"흠... 자네는 좋은 대장간을 찾는 법을 아니?\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0056776","time":"2026-03-28T13:45:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"망치로 쇠를 때리는 경쾌한 소리가 울려 퍼졌다. 지붕을 위로 화로의 열기와 함께 연기가 몽실몽실 떠올랐다.","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056777","time":"2026-03-28T13:46:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"덩달아 션의 목소리도 커진다.\n\n\"가장 시끄러운 곳을 찾아야지. 제일 일감이 많은 곳.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056778","time":"2026-03-28T13:51:00+09:00","room":"RP III","name":"토르번 팔켄하인 / 대장장이·도란","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"저긴 어떤가.\"\n\n토르번이 가리키는 손가락에는, 근육질의 험악하게 생긴 대머리 중년 하나가 망치를 두들기며 검을 만들고 있었다. 굳이 말하자면 항상 화를 낼 거 같이 생긴 머독과 닮아있었다.\n\n군대에서 발주라도 받은 듯 평범한 아밍소드를 잔뜩 바닥에 나열해놓은 채로 그는 손가락질한 토르번을 곁눈질로 흘겨보았다.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0056779","time":"2026-03-28T13:52:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"\"가봐야 알겠지, 뭐.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056780","time":"2026-03-28T13:53:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"토르번이 가리킨 길 건너 대장간으로 일단 가보았다.","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056781","time":"2026-03-28T13:55:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"\"주인장! 칼을 사려고 하는데. 롱소드로, 전장 120cm 전후, 날 길이는 90cm 이상 되는 걸로.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056782","time":"2026-03-28T13:57:00+09:00","room":"RP III","name":"토르번 팔켄하인 / 대장장이·도란","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"주인장은 손님을 반갑게 맞이할 여유가 없는지 힐긋 거리다가.\n\n- 지금은 주문 물량이 많아서 제법 걸리네만.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0056783","time":"2026-03-28T14:04:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"\"그럼 미리 있는 것들로 봐야겠군.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056784","time":"2026-03-28T14:04:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"\"별로 대단한 칼을 찾는 건 아니오. 손에 맞으면 다 괜찮소.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056785","time":"2026-03-28T14:07:00+09:00","room":"RP III","name":"토르번 팔켄하인 / 대장장이·도란","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"그는 잠시 대답없이 계속해서 망치질을 하다가 소리내었다.\n\n- 도란! 손님 맞이해라!\n\n그러자 열셋 정도 되어보이는 나이의 소년이 검을 닦다가 일어나 장부를 챙겨서 쫄레쫄레.\n\n- 그럼 여기 벽면에 있는 검들을 확인해보시겠어요?","characters":["P-7ba611cf90be"]},{"id":"RP-III-0056786","time":"2026-03-28T14:07:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"\"도란? 굉장히 믿음직한 이름일세.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056787","time":"2026-03-28T14:08:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"\"자네 혹시 반지도 가지고 있나?\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056788","time":"2026-03-28T14:08:00+09:00","room":"RP III","name":"토르번 팔켄하인 / 대장장이·도란","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"- 반, 반지요? 아버지가 주신 게 있긴 한데... 스승님께서 끼지 말라고 하셔서요...","characters":["P-7ba611cf90be"]},{"id":"RP-III-0056789","time":"2026-03-28T14:13:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"벽면에 있는 중간 길이의 칼을 집어서 빙글 돌려보았다.\n\n\"이건 퍼멀만 너무 커서 무게 중심이 안 맞는군.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056790","time":"2026-03-28T14:17:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"가장 긴 칼조차 션에게 평범한 롱소드처럼 보였다. 이번에도 두어번 가로로 휘둘러보고는 다시 벽에 걸었다.\n\n\"이건 너무 가볍고 날이 얇아.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056791","time":"2026-03-28T14:22:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"\"에휴… 도란 군, 빨리 다른 대장간 알아보게. 칼 상태가 영 파이구만.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056792","time":"2026-03-28T14:24:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"\"자네 스승은 아밍소드 전문이지? 롱소드는 밸런스를 맞추기 어려워하는 모양이네.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056793","time":"2026-03-28T14:36:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"션은 이후 온갖 칼들을 집어보고 휘둘러보았지만 마음에 드는 건 찾을 수 없었다.","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056794","time":"2026-03-28T14:36:00+09:00","room":"RP III","name":"션 / 데미간 재단사","profile":"션","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0056795","time":"2026-03-28T14:36:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]}]};
